# Add a claim to a person. Validate first so a bad amount or date is a 400 and writes nothing,
# not masked by a 404 for a missing person.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaim
  next: snapshot
# Keep the figures as they were, so the change can audit the ones it moves.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: build
build:
  class: net.officefloor.hq.app.claim.BuildClaim
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: record
# Audit only once the change is saved: a refused change writes no line.
record:
  class: net.officefloor.hq.app.claim.RecordClaimAdded
  govern: [ transaction ]
  next: rollup
# After the change's own lines: a line per person whose figures moved, then the totals if they did.
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaimCreated
  govern: [ transaction ]
# Open the selected claims together. Each that can be opened is opened (and audited) as a single
# open would be, in list order; each that cannot is left as it is. Answers how many of each.
validate:
  class: net.officefloor.hq.app.claim.ValidateBulkOpen
  next: open
open:
  class: net.officefloor.hq.app.claim.OpenClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithBulkOpen
  govern: [ transaction ]
# Quick-add a DRAFT claim by person name, creating the person (grade A) when the name is not on the
# sheet. One change: everything is checked before anything is saved, so a refused claim leaves no
# new person behind and writes nothing.
validate:
  class: net.officefloor.hq.app.quickadd.ValidateQuickAdd
  next: snapshot
# Keep the figures as they were, so the change can audit the ones it moves.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: find
find:
  class: net.officefloor.hq.app.quickadd.FindQuickAddPerson
  govern: [ transaction ]
  next: refuse
refuse:
  class: net.officefloor.hq.app.quickadd.RefuseClosedQuickAdd
  govern: [ transaction ]
  next: savePerson
